css:
/* --- 基础容器与字体 --- */
.print-format {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "HarmonyOSHans-fallback", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif !important;
    font-size: 13px;
    line-height: 1.5;
    color: #171717;
    background: white;
    padding: 0.5in !important; /* 适当缩小页边距增加内容空间 */
}

/* --- 表头 (Letterhead) 优化 --- */
.letter-head {
    margin-bottom: 20px !important; /* 压缩表头与正文间距 */
    padding: 0 !important;
}

.letter-head table {
    border-bottom: 2px solid #171717; /* 加粗底线提升稳重感 */
    padding-bottom: 0px;
}

/* --- 正文标题区域 --- */
.print-format-body {
    padding: 0 !important; /* 移除多余内边距 */
}

.print-format-body h2 {
    font-size: 20px;
    font-weight: 700;
    margin: 0;
    letter-spacing: 1px;
}

.title {
    color: #74808b !important; /* 统一标签颜色 */
    font-size: 12px;
    font-weight: normal;
}

/* --- 物料表格 (Items Table) 精细化 --- */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
    border: 1px solid #ededed;
}

.items-table th {
    background-color: #f8f9fa; /* 极浅灰背景 */
    color: #4c5a67;
    font-weight: 600;
    font-size: 12px;
    text-transform: none;
    padding: 8px !important;
    border: 1px solid #ededed;
}

.items-table td {
    padding: 8px !important;
    border: 1px solid #ededed;
    vertical-align: middle !important;
}

/* 物品代码与名称的排版 */
.items-table td div[style*="font-weight: bold"] {
    font-size: 13px;
    margin-bottom: 2px;
}

.items-table td div[style*="color: #666"] {
    font-size: 11px;
    color: #888 !important;
}

/* 数量列突出显示 */
.items-table td.text-right span[style*="font-size: 16px"] {
    font-size: 15px !important;
    color: #000;
}

/* --- 确认框样式 --- */
.items-table .text-center div[style*="border: 1px solid #ccc"] {
    border: 1px solid #bbb !important;
    border-radius: 2px;
    width: 16px !important; /* 稍微缩小复选框，更精致 */
    height: 16px !important;
}

/* --- 打印适配 (解决图片被强制拉伸) --- */
body:last-child .print-format td img {
    width: auto !important; /* 强制覆盖您提供的 100% 规则 */
    max-width: 100%;
}

/** 修复溢出导出多余空白页问题 */
#screenity-ui {
    overflow: hidden;
    display: none !important;
}
